def open_claims_for_confirmed_supports(apps, schema_editor):
    """Les appuis remboursables déjà confirmés avant ce lot reçoivent leur créance (3 échéances à 30 jours, la
    première 90 jours après la confirmation)."""
    from datetime import timedelta

    Support, Claim, Installment = (apps.get_model("production", n) for n in ("Support", "Claim", "Installment"))
    for s in Support.objects.filter(repayable=True, status="confirme", value_xof__gt=0, producer__user__isnull=False):
        c = Claim.objects.create(kind="appui", debtor_id=s.producer.user_id, creditor_id=s.delivered_by_id, support=s,
                                 label=s.item, amount_xof=s.value_xof, department=s.producer.department)
        base, extra = divmod(s.value_xof, 3)
        start = (s.confirmed_at or s.created_at).date() + timedelta(days=90)
        for n, amount in enumerate([base, base, base + extra]):
            Installment.objects.create(claim=c, rank=n + 1, due_on=start + timedelta(days=30 * n), amount_xof=amount)


